import{bt as e,n as t,ot as n,st as r}from"./chunks/framework.CxhjsvYc.js";var i=JSON.parse(`{"title":"FD Cal — engineering audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/"}],["meta",{"property":"og:title","content":"FD Cal — engineering audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/"}],["meta",{"name":"twitter:title","content":"FD Cal — engineering audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/index.md","filePath":"audits/index.md","lastUpdated":1794227887000}`),a={name:`audits/index.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="fd-cal-—-engineering-audit" tabindex="-1">FD Cal — engineering audit <a class="header-anchor" href="#fd-cal-—-engineering-audit" aria-label="Permalink to “FD Cal — engineering audit”">​</a></h1><p><strong>Re-audit date:</strong> 9 November 2026<br><strong>Base audited:</strong> <code>dev</code> at PR #81 squash merge <code>85f2043c4d06ac4f7bcd65ec5aa18452c98ff38a</code><br><strong>Active follow-up branch:</strong> <code>audit/owner-feedback-followups</code><br><strong>Ruleset:</strong> <a href="https://github.com/aaron-fredrick/RULESETS" target="_blank" rel="noreferrer">aaron-fredrick/RULESETS</a></p><p>This index tracks the audit, owner decisions and follow-up implementation separately. The <a href="./OWNER-FEEDBACK-RESEARCH.html">owner-feedback research register</a> contains external research; the <a href="./IMPLEMENTATION-PLAN.html">implementation plan</a> contains implementation evidence, acceptance criteria and remaining work.</p><h2 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to “Reports”">​</a></h2><table tabindex="0"><thead><tr><th>Report</th><th>Coverage</th></tr></thead><tbody><tr><td><a href="./EXECUTIVE-SUMMARY.html">Executive summary</a></td><td>Current finding dispositions, verification status and release readiness</td></tr><tr><td><a href="./IMPLEMENTATION-PLAN.html">Implementation plan</a></td><td>Owner decisions, implementation evidence, acceptance criteria and remaining tasks</td></tr><tr><td><a href="./OWNER-FEEDBACK-RESEARCH.html">Owner-feedback research</a></td><td>Bank product, AIT, transfer-fee, data freshness, search architecture, QA and legal research</td></tr><tr><td><a href="./SEARCH-BUDGET-CALIBRATION.html">Search budget calibration</a></td><td>Controlled 5k/10k/20k/unlimited × 15/30/60s comparison</td></tr><tr><td><a href="./../finance/INTEREST-DAY-COUNT.html">Interest day-count note</a></td><td>Retained start-year 365/366 elapsed-day convention</td></tr><tr><td><a href="./../data/BANK-DATA-METADATA.html">Bank dataset metadata</a></td><td>Independent review, economic-update and schema-version dates</td></tr><tr><td><a href="./ENGINE-CORE.html">Engine and financial core</a></td><td>Dates, interest, FD cash flows, simulation lifecycle, balances and results</td></tr><tr><td><a href="./STRATEGIES-AND-SEARCH.html">Strategies and search</a></td><td>Greedy, GSS, Absolute R, Absolute R+, search budgets, parity and architecture</td></tr><tr><td><a href="./WEB-UI-UX-ACCESSIBILITY.html">Web UI, UX and accessibility</a></td><td>Form flows, responsive layout, motion, keyboard and screen-reader semantics</td></tr><tr><td><a href="./REPORTING-OUTPUTS.html">Reporting and outputs</a></td><td>In-app metrics, standalone HTML, ledger, charts and financial presentation</td></tr><tr><td><a href="./DATA-AND-FINANCIAL-ASSUMPTIONS.html">Data and financial assumptions</a></td><td>Catalogue quality, provenance, eligibility, fees, AIT and product constraints</td></tr><tr><td><a href="./SECURITY-PRIVACY.html">Security and privacy</a></td><td>Untrusted configuration, DOM rendering, local storage and client-side exposure</td></tr><tr><td><a href="./BUILD-DEPLOYMENT-AND-QUALITY.html">Build, deployment and quality</a></td><td>GitHub Actions, Pages composition, dev preview, tests and operational gaps</td></tr></tbody></table><h2 id="current-disposition" tabindex="-1">Current disposition <a class="header-anchor" href="#current-disposition" aria-label="Permalink to “Current disposition”">​</a></h2><ul><li><strong>Completed on dev:</strong> SEC-01, FIN-01/02, ENG-05, DEPLOY-01, UI-01/02/03, DATA-01/04, FIN-03 and PRIV-01/02.</li><li><strong>Implemented on follow-up branch:</strong> ENG-01/02/03/04, SEARCH-01 calibration and QA-01 Playwright suite.</li><li><strong>Partially complete:</strong> SEARCH-03 now includes four-strategy settlement and booking/maturity/installment/fee fixtures. Greedy&#39;s strict-outflow liquidity-reservation defect is fixed and regression-tested; broader multi-account planner parity remains. QA-REP-01 automated report assertions pass; offline/chart checks and manual print/accessibility review remain.</li><li><strong>Metadata contract complete; source review pending:</strong> DATA-06 separates source review, material economic updates and schema version. All 29 indexed bank rows still have blank review/update dates pending genuine source checks.</li><li><strong>Open verification:</strong> WEB-SEC-02 production and dev Pages response headers.</li><li><strong>Deferred:</strong> SEARCH-02 broad decomposition, DATA-03 special-product modelling, richer DATA-05 transfer-channel fees, main-branch preview assembler port and external legal counsel review.</li><li><strong>Scope closed:</strong> DATA-02 age-segment controls are filters, not depositor identity or eligibility checks.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to “Verification”">​</a></h2><p>The latest verified full workflow for the current SEARCH-03 fix is <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42598559354" target="_blank" rel="noreferrer">42598559354</a>: all 268 Node tests passed, along with syntax checks, production/dev browser builds, all six Chromium browser tests, documentation-preservation build and workflow YAML parsing. This supersedes the earlier SEARCH-03 regression attempts.</p><p>Automated report checks now cover semantic event-ledger headers, 320px document overflow and print table width. Static inspection and automated smoke tests do not establish screen-reader output, full WCAG conformance, real-device behaviour, actual printed/PDF pagination, live bank rates or deployed HTTP response headers.</p><p>This is a risk-based source audit and targeted implementation verification. It is not a line-by-line proof, financial-product certification, penetration test, legal opinion, full WCAG assessment or external revalidation of every bank rate and fee.</p><h2 id="crawler-and-release-path-policy" tabindex="-1">Crawler and release-path policy <a class="header-anchor" href="#crawler-and-release-path-policy" aria-label="Permalink to “Crawler and release-path policy”">​</a></h2><p>The <code>/dev/</code> subtree is a public preview, not an indexable production destination. Root <code>robots.txt</code> permits crawlers to fetch preview pages so they can observe <code>noindex,nofollow</code>; every generated dev HTML entry point must carry that directive; and the production sitemap must contain only canonical production URLs, never preview URLs. <code>robots.txt</code> is crawler guidance, not access control. Production docs output merges canonical root and <code>/web/</code> URLs into the sitemap. Preview builds omit sitemap output and mark dev HTML noindex. This is a verified positive control, not an open finding.</p><h2 id="latest-verification-checkpoint" tabindex="-1">Latest verification checkpoint <a class="header-anchor" href="#latest-verification-checkpoint" aria-label="Permalink to “Latest verification checkpoint”">​</a></h2><p>Greedy now reserves cumulative strict outflows due before candidate maturity, invests only residual cash when it meets the FD minimum, and skips unsafe ranked candidates unless their maturity is on or before the due date. Three regression cases cover partial cash reservation, shorter-tenor fallback and cumulative obligations. The shared runtime remains authoritative for settlement. Workflow <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42598559354" target="_blank" rel="noreferrer">42598559354</a> passed all 268 tests and the complete automated pipeline. SEARCH-03 remains partial because broader multi-account and cross-strategy planner parity remains.</p><h2 id="_9-november-2026-—-ship-gate-recheck" tabindex="-1">9 November 2026 — ship-gate recheck <a class="header-anchor" href="#_9-november-2026-—-ship-gate-recheck" aria-label="Permalink to “9 November 2026 — ship-gate recheck”">​</a></h2><p>Current verified implementation head <code>aa8684e0999a9554af3f6c0185a4eeb0d9e5a233</code> passes <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42598559354" target="_blank" rel="noreferrer">workflow 42598559354</a>. Greedy&#39;s strict-outflow liquidity-reservation gap is fixed inside its ranked candidate-selection rules; no shared-runtime settlement behaviour was changed.</p><p>The existing <a href="https://github.com/aaron-fredrick/FD-Calculator/pull/82" target="_blank" rel="noreferrer">PR #82</a> remains a draft. SEARCH-03 is improved but not fully closed: broader cross-strategy planner parity remains, as do extended report/accessibility QA, bank-source review and deployed response-header verification. Those later phases remain queued.</p>`,18)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};